def _validate_stored_operation(entry: Any) -> tuple[str, dict[str, Any]]:
    """Validate one persisted operation record against the input constraints.

    Returns the ``(replica_id, operation)`` pair. Raises PersistenceError on
    any structural mismatch or constraint violation.
    """
    if not isinstance(entry, dict) or set(entry.keys()) != {"replicaId", "operation"}:
        raise PersistenceError("each operation record must be an object with replicaId and operation")
    replica_id = entry["replicaId"]
    operation_raw = entry["operation"]
    if not isinstance(replica_id, str) or replica_id == "":
        raise PersistenceError("stored replicaId must be a non-empty string")
    if not isinstance(operation_raw, dict) or set(operation_raw.keys()) != {
        "operationId",
        "key",
        "value",
        "clock",
    }:
        raise PersistenceError("stored operation has an unexpected shape")
    try:
        operation = parse_operation_payload(operation_raw, replica_id)
    except ValueError as exc:
        raise PersistenceError(f"stored operation violates input constraints: {exc}") from exc
    return replica_id, operation


def _validate_stored_checkpoints(
    document: Any, log_length: int
) -> dict[str, int]:
    """Validate the optional ``checkpoints`` section of a data file.

    Returns a clean ``{peerId: cursor}`` mapping. The section is optional
    (a version:1 file written before checkpoints existed simply has none);
    when present it must be an object of non-empty peer ids mapped to
    non-boolean non-negative integers no greater than the accepted-log
    length, since a cursor may never name an unaccepted record.
    """
    if "checkpoints" not in document:
        return {}
    raw = document["checkpoints"]
    if not isinstance(raw, dict):
        raise PersistenceError("data file checkpoints must be an object")
    checkpoints: dict[str, int] = {}
    for peer_id, cursor in raw.items():
        if not isinstance(peer_id, str) or peer_id == "":
            raise PersistenceError("checkpoint peerId must be a non-empty string")
        if isinstance(cursor, bool) or not isinstance(cursor, int) or cursor < 0:
            raise PersistenceError("checkpoint cursor must be a non-negative integer")
        if cursor > log_length:
            raise PersistenceError(
                f"checkpoint cursor {cursor} for {peer_id!r} is past the accepted log"
            )
        checkpoints[peer_id] = cursor
    return checkpoints


def _validate_stored_policies(
    document: Any, identities: set[tuple[str, str]]
) -> dict[tuple[str, str], str]:
    """Validate the optional ``policies`` section of a data file.

    Returns a clean ``{(replicaId, operationId): policy}`` mapping. The
    section is optional (a version:1 file written before automatic
    resolutions recorded their policy simply has none); when present it must
    be a list of ``{"replicaId", "operationId", "policy"}`` records with a
    known policy string, one per identity, and every identity must name an
    accepted operation, since a policy binding is committed atomically
    together with its operation.
    """
    if "policies" not in document:
        return {}
    raw = document["policies"]
    if not isinstance(raw, list):
        raise PersistenceError("data file policies must be a list")
    policies: dict[tuple[str, str], str] = {}
    for entry in raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {
            "replicaId",
            "operationId",
            "policy",
        }:
            raise PersistenceError(
                "each policy record must be an object with replicaId, operationId, policy"
            )
        replica_id = entry["replicaId"]
        operation_id = entry["operationId"]
        policy = entry["policy"]
        if not isinstance(replica_id, str) or replica_id == "":
            raise PersistenceError("policy replicaId must be a non-empty string")
        if not isinstance(operation_id, str) or operation_id == "":
            raise PersistenceError("policy operationId must be a non-empty string")
        if policy not in AUTO_RESOLVE_POLICIES:
            raise PersistenceError(f"unknown stored policy: {policy!r}")
        identity = (replica_id, operation_id)
        if identity in policies:
            raise PersistenceError(f"duplicate policy binding {identity!r} in data file")
        if identity not in identities:
            raise PersistenceError(
                f"policy binding {identity!r} names no accepted operation"
            )
        policies[identity] = policy
    return policies


def _validate_stored_transactions(
    document: Any, identities: set[tuple[str, str]]
) -> dict[str, list[dict[str, Any]]]:
    """Validate the optional ``transactions`` section of a data file.

    Returns a clean ``{transactionId: entries}`` mapping. The section is
    optional (a version:1 file written before transactions existed simply
    has none); when present it must be a list of
    ``{"transactionId", "operations"}`` records with a non-empty distinct
    transaction id each, the entries must satisfy the live transaction
    constraints, and every entry identity must name an accepted operation,
    since a transaction binding is committed atomically together with its
    operations.
    """
    if "transactions" not in document:
        return {}
    raw = document["transactions"]
    if not isinstance(raw, list):
        raise PersistenceError("data file transactions must be a list")
    transactions: dict[str, list[dict[str, Any]]] = {}
    for record in raw:
        if not isinstance(record, dict) or set(record.keys()) != {
            "transactionId",
            "operations",
        }:
            raise PersistenceError(
                "each transaction record must be an object with transactionId and operations"
            )
        transaction_id = record["transactionId"]
        if not isinstance(transaction_id, str) or transaction_id == "":
            raise PersistenceError("transaction id must be a non-empty string")
        if transaction_id in transactions:
            raise PersistenceError(f"duplicate transaction {transaction_id!r} in data file")
        try:
            entries = _parse_transaction_entries(record["operations"])
        except ValueError as exc:
            raise PersistenceError(
                f"stored transaction violates input constraints: {exc}"
            ) from exc
        for entry in entries:
            identity = (entry["replicaId"], entry["operationId"])
            if identity not in identities:
                raise PersistenceError(
                    f"transaction {transaction_id!r} names no accepted operation "
                    f"for identity {identity!r}"
                )
        transactions[transaction_id] = entries
    return transactions


def _validate_stored_acks(
    document: Any,
    checkpoints: dict[str, int],
    records: list[tuple[str, dict[str, Any]]],
) -> dict[tuple[str, str], dict[str, Any]]:
    """Validate the optional ``acks`` section of a data file.

    Returns a clean ``{(peerId, ackId): {"cursor", "operations"}}``
    mapping. The section is optional (a version:1 file written before
    consumption receipts existed simply has none, and recovers with no
    receipt bindings); when present it must be a list of
    ``{"peerId", "ackId", "cursor", "operations"}`` records satisfying the
    live acknowledge constraints, one per ``(peerId, ackId)`` pair. Because
    a receipt is committed atomically with the checkpoint advance it
    caused, every binding must name a registered peer whose checkpoint has
    reached at least the binding's cursor, and the covered segment must
    match the accepted log exactly — anything else is a corrupt file.
    """
    if "acks" not in document:
        return {}
    raw = document["acks"]
    if not isinstance(raw, list):
        raise PersistenceError("data file acks must be a list")
    acks: dict[tuple[str, str], dict[str, Any]] = {}
    for entry in raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {
            "peerId",
            "ackId",
            "cursor",
            "operations",
        }:
            raise PersistenceError(
                "each ack record must be an object with peerId, ackId, cursor, operations"
            )
        peer_id = entry["peerId"]
        ack_id = entry["ackId"]
        cursor = entry["cursor"]
        if not isinstance(peer_id, str) or peer_id == "":
            raise PersistenceError("ack peerId must be a non-empty string")
        if not isinstance(ack_id, str) or ack_id == "":
            raise PersistenceError("ackId must be a non-empty string")
        if isinstance(cursor, bool) or not isinstance(cursor, int) or cursor < 0:
            raise PersistenceError("ack cursor must be a non-negative integer")
        try:
            operations = _parse_ack_operations(entry["operations"])
        except ValueError as exc:
            raise PersistenceError(
                f"stored ack violates input constraints: {exc}"
            ) from exc
        key = (peer_id, ack_id)
        if key in acks:
            raise PersistenceError(f"duplicate ack binding {key!r} in data file")
        registered = checkpoints.get(peer_id)
        if registered is None or registered < cursor:
            raise PersistenceError(
                f"ack binding {key!r} names a peer whose checkpoint has not reached it"
            )
        start = cursor - len(operations)
        if start < 0 or cursor > len(records):
            raise PersistenceError(
                f"ack binding {key!r} covers a segment outside the accepted log"
            )
        for (replica_id, operation), identity in zip(records[start:cursor], operations):
            if (
                replica_id != identity["replicaId"]
                or operation["operationId"] != identity["operationId"]
            ):
                raise PersistenceError(
                    f"ack binding {key!r} does not match the accepted log segment"
                )
        acks[key] = {"cursor": cursor, "operations": operations}
    return acks


def _validate_stored_repair_suggestion(entry: Any) -> dict[str, Any]:
    """Validate one stored normalized repair-execution suggestion.

    Mirrors the normalized shapes :func:`parse_replication_repairs_batch`
    produces: an interval action (``resend``/``deduplicate``/
    ``correct_cursor``) carries ``action``, ``ackId``, and matching
    ``location``/``target`` interval boundaries; a ``correct_identity``
    action carries a ``location``/``target`` log position and the
    ``expected``/``observed`` identities. Raises PersistenceError on any
    violation.
    """
    if not isinstance(entry, dict):
        raise PersistenceError("each repair suggestion must be an object")
    action = entry.get("action")
    if action not in REPAIR_ACTIONS:
        raise PersistenceError(f"unknown repair action {action!r}")
    ack_id = entry.get("ackId")
    if not isinstance(ack_id, str) or ack_id == "":
        raise PersistenceError("repair suggestion ackId must be a non-empty string")
    if action in (*REPAIR_INTERVAL_ACTIONS, "correct_cursor"):
        if set(entry.keys()) != {"action", "ackId", "location", "target"}:
            raise PersistenceError(
                f"{action} repair suggestion must have only action, ackId, location, target"
            )
        try:
            location = _repair_boundary(entry["location"])
            target = _repair_boundary(entry["target"])
        except ValueError as exc:
            raise PersistenceError(f"stored repair boundary is invalid: {exc}") from exc
        return {
            "action": action,
            "ackId": ack_id,
            "location": location,
            "target": target,
        }
    if set(entry.keys()) != {
        "action",
        "ackId",
        "location",
        "target",
        "expected",
        "observed",
    }:
        raise PersistenceError(
            "correct_identity repair suggestion must have only action, ackId, "
            "location, target, expected, observed"
        )
    location = entry["location"]
    target = entry["target"]
    if not isinstance(location, dict) or set(location.keys()) != {"position"}:
        raise PersistenceError("stored identity repair location must have only position")
    if not isinstance(target, dict) or set(target.keys()) != {"position"}:
        raise PersistenceError("stored identity repair target must have only position")
    position = location["position"]
    if isinstance(position, bool) or not isinstance(position, int) or position < 0:
        raise PersistenceError("stored identity repair position must be a non-negative integer")
    if target["position"] != position:
        raise PersistenceError("stored identity repair target position must match its location")
    try:
        expected = _repair_identity(entry["expected"])
        observed = _repair_identity(entry["observed"])
    except ValueError as exc:
        raise PersistenceError(f"stored repair identity is invalid: {exc}") from exc
    return {
        "action": action,
        "ackId": ack_id,
        "location": {"position": position},
        "target": {"position": position},
        "expected": expected,
        "observed": observed,
    }


def _validate_stored_repair_results(
    raw: Any, suggestion_actions: list[str]
) -> list[dict[str, Any]]:
    """Validate the stored per-suggestion results of one repair execution.

    ``suggestion_actions`` is the action of each normalized suggestion in
    order; the result count and per-item action must both match it.
    """
    count = len(suggestion_actions)
    if not isinstance(raw, list) or len(raw) != count:
        raise PersistenceError("repair results must be a list matching its suggestions")
    results: list[dict[str, Any]] = []
    for index, entry in enumerate(raw):
        if not isinstance(entry, dict) or set(entry.keys()) != {"action", "boundary"}:
            raise PersistenceError("each repair result must have only action and boundary")
        action = entry["action"]
        if action not in REPAIR_ACTIONS:
            raise PersistenceError(f"unknown repair result action {action!r}")
        if action != suggestion_actions[index]:
            raise PersistenceError("repair result action must match its suggestion")
        boundary = entry["boundary"]
        if action == "correct_identity":
            if not isinstance(boundary, dict) or set(boundary.keys()) != {"position"}:
                raise PersistenceError("identity repair result boundary must be a position")
            position = boundary["position"]
            if isinstance(position, bool) or not isinstance(position, int) or position < 0:
                raise PersistenceError("identity repair result position must be a non-negative integer")
            results.append({"action": action, "boundary": {"position": position}})
        else:
            try:
                interval = _repair_boundary(boundary)
            except ValueError as exc:
                raise PersistenceError(f"stored repair boundary is invalid: {exc}") from exc
            results.append({"action": action, "boundary": interval})
    return results


def _validate_stored_repairs(
    document: Any,
    checkpoints: dict[str, int],
    records: list[tuple[str, dict[str, Any]]],
) -> dict[tuple[str, str], dict[str, Any]]:
    """Validate the optional ``repairExecutions`` section of a data file.

    Returns a clean ``{(peerId, ackId): binding}`` mapping of committed
    conditional repair executions. The section is optional (a version:1
    file written before the repair entries existed recovers with no
    repair bindings). When present it is a list of records, one per
    ``(peerId, ackId)`` pair, each carrying exactly ``peerId``,
    ``ackId``, ``expectedCheckpoint``, ``expectedReceipts``,
    ``suggestions``, ``results``, and ``cursor``. Because a repair
    commits its restored checkpoint atomically, every binding must name a
    registered peer whose checkpoint has reached the binding's cursor;
    the cursor may not exceed the recovered log length. Anything else is
    a corrupt file.
    """
    if "repairExecutions" not in document:
        return {}
    raw = document["repairExecutions"]
    if not isinstance(raw, list):
        raise PersistenceError("data file repairExecutions must be a list")
    repairs: dict[tuple[str, str], dict[str, Any]] = {}
    for entry in raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {
            "peerId",
            "ackId",
            "expectedCheckpoint",
            "expectedReceipts",
            "suggestions",
            "results",
            "cursor",
        }:
            raise PersistenceError(
                "each repair record must be an object with peerId, ackId, "
                "expectedCheckpoint, expectedReceipts, suggestions, results, cursor"
            )
        peer_id = entry["peerId"]
        ack_id = entry["ackId"]
        expected_checkpoint = entry["expectedCheckpoint"]
        cursor = entry["cursor"]
        if not isinstance(peer_id, str) or peer_id == "":
            raise PersistenceError("repair peerId must be a non-empty string")
        if not isinstance(ack_id, str) or ack_id == "":
            raise PersistenceError("repair ackId must be a non-empty string")
        for name, value in (
            ("expectedCheckpoint", expected_checkpoint),
            ("cursor", cursor),
        ):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise PersistenceError(f"repair {name} must be a non-negative integer")
        if not _is_sha256_hex64(entry["expectedReceipts"]):
            raise PersistenceError(
                "repair expectedReceipts must be 64 lowercase hexadecimal characters"
            )
        suggestions_raw = entry["suggestions"]
        if not isinstance(suggestions_raw, list) or not (
            REPAIR_BATCH_MIN <= len(suggestions_raw) <= REPAIR_BATCH_MAX
        ):
            raise PersistenceError("repair suggestions must be a list of 1-100 entries")
        suggestions = [
            _validate_stored_repair_suggestion(item) for item in suggestions_raw
        ]
        for index in range(1, len(suggestions)):
            if REPAIR_ACTIONS.index(suggestions[index]["action"]) < REPAIR_ACTIONS.index(
                suggestions[index - 1]["action"]
            ):
                raise PersistenceError("stored repair suggestions must be in processing order")
        results = _validate_stored_repair_results(
            entry["results"], [item["action"] for item in suggestions]
        )
        key = (peer_id, ack_id)
        if key in repairs:
            raise PersistenceError(f"duplicate repair binding {key!r} in data file")
        registered = checkpoints.get(peer_id)
        if registered is None or registered < cursor:
            raise PersistenceError(
                f"repair binding {key!r} names a peer whose checkpoint has not reached it"
            )
        if cursor > len(records) or cursor < expected_checkpoint:
            raise PersistenceError(
                f"repair binding {key!r} restores a cursor outside the recovered log"
            )
        repairs[key] = {
            "expectedCheckpoint": expected_checkpoint,
            "expectedReceipts": entry["expectedReceipts"],
            "suggestions": suggestions,
            "results": results,
            "cursor": cursor,
        }
    return repairs


def _is_sha256_hex64(value: Any) -> bool:
    """Return True for exactly 64 lowercase hexadecimal characters."""
    return isinstance(value, str) and len(value) == 64 and all(
        ("0" <= ch <= "9") or ("a" <= ch <= "f") for ch in value
    )


def _validate_stored_policy_events(document: Any) -> list[dict[str, Any]]:
    """Validate the optional ``policyEvents`` section of a data file.

    Returns a clean ordered list of policy-change events, each
    ``{"sequence", "digest", "tokens"}``. The section is optional (a
    version:1 file written before scope-policy change auditing existed
    simply has none, and recovers with an empty history); when present it
    must be a list whose entries carry exactly those three keys:
    ``sequence`` is a non-boolean positive integer starting at 1 and
    increasing without gaps, ``digest`` is 64 lowercase hexadecimal
    characters (the SHA-256 recorded at reload time), and ``tokens`` is a
    non-boolean non-negative integer (the reloaded policy's entry count).
    Anything else is a corrupt file.
    """
    if "policyEvents" not in document:
        return []
    raw = document["policyEvents"]
    if not isinstance(raw, list):
        raise PersistenceError("data file policyEvents must be a list")
    events: list[dict[str, Any]] = []
    for entry in raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {
            "sequence",
            "digest",
            "tokens",
        }:
            raise PersistenceError(
                "each policy event must be an object with sequence, digest, tokens"
            )
        sequence = entry["sequence"]
        tokens = entry["tokens"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise PersistenceError("policy event sequence must be a positive integer")
        if sequence != len(events) + 1:
            raise PersistenceError(
                "policy event sequences must start at 1 and continue without gaps"
            )
        if not _is_sha256_hex64(entry["digest"]):
            raise PersistenceError("policy event digest must be 64 lowercase hex characters")
        if isinstance(tokens, bool) or not isinstance(tokens, int) or tokens < 0:
            raise PersistenceError("policy event tokens must be a non-negative integer")
        events.append(
            {"sequence": sequence, "digest": entry["digest"], "tokens": tokens}
        )
    return events


def _validate_stored_compensations(
    document: Any,
    identities: set[tuple[str, str]],
    transactions: dict[str, list[dict[str, Any]]],
) -> dict[str, dict[str, Any]]:
    """Validate the optional ``compensations`` section of a data file.

    Returns a clean ``{compensationId: binding}`` mapping. The section
    is optional (a version:1 file written before compensations existed
    simply has none); when present it must be a list of
    ``{"compensationId", "transactionId", "expectedPlanDigest",
    "operations", "status"}`` records with a non-empty distinct
    compensation id each, the transaction id naming a committed
    transaction, the expected plan digest being 64 lowercase
    hexadecimal characters, the entries satisfying the live
    compensation constraints with every entry identity naming an
    accepted operation (a compensation binding is committed atomically
    together with its operations), and the status being
    ``"committed"``.
    """
    if "compensations" not in document:
        return {}
    raw = document["compensations"]
    if not isinstance(raw, list):
        raise PersistenceError("data file compensations must be a list")
    compensations: dict[str, dict[str, Any]] = {}
    for record in raw:
        if not isinstance(record, dict) or set(record.keys()) != {
            "compensationId",
            "transactionId",
            "expectedPlanDigest",
            "operations",
            "status",
        }:
            raise PersistenceError(
                "each compensation record must be an object with compensationId, "
                "transactionId, expectedPlanDigest, operations, status"
            )
        compensation_id = record["compensationId"]
        transaction_id = record["transactionId"]
        if not isinstance(compensation_id, str) or compensation_id == "":
            raise PersistenceError("compensation id must be a non-empty string")
        if compensation_id in compensations:
            raise PersistenceError(
                f"duplicate compensation {compensation_id!r} in data file"
            )
        if not isinstance(transaction_id, str) or transaction_id == "":
            raise PersistenceError("compensation transactionId must be a non-empty string")
        if transaction_id not in transactions:
            raise PersistenceError(
                f"compensation {compensation_id!r} names no committed transaction "
                f"{transaction_id!r}"
            )
        expected_digest = record["expectedPlanDigest"]
        if not _is_sha256_hex64(expected_digest):
            raise PersistenceError(
                "compensation expectedPlanDigest must be 64 lowercase hex characters"
            )
        try:
            entries = _parse_compensation_entries(record["operations"])
        except ValueError as exc:
            raise PersistenceError(
                f"stored compensation violates input constraints: {exc}"
            ) from exc
        for entry in entries:
            identity = (entry["replicaId"], entry["operationId"])
            if identity not in identities:
                raise PersistenceError(
                    f"compensation {compensation_id!r} names no accepted operation "
                    f"for identity {identity!r}"
                )
        status = record["status"]
        if status != "committed":
            raise PersistenceError(f"unknown compensation status {status!r}")
        compensations[compensation_id] = {
            "transactionId": transaction_id,
            "expectedPlanDigest": expected_digest,
            "operations": entries,
            "status": status,
        }
    return compensations

    """Classify two already-known-different clocks relative to each other.

    Returns ``"L"`` when ``clock_a`` dominates ``clock_b``, ``"R"`` when
    ``clock_b`` dominates ``clock_a``, and ``"C"`` when the clocks are
    concurrent — neither dominates the other. Equal clocks are never
    compared: the callers only ask for a direction when the clocks
    differ. Missing components count as 0, exactly as in
    :func:`clock_dominates`.
    """
    if clock_dominates(clock_a, clock_b):
        return "L"
    if clock_dominates(clock_b, clock_a):
        return "R"
    return "C"


def _validate_clock(clock: Any, replica_id: str) -> dict[str, int]:
    """Validate a vector clock for ``replica_id`` and return a clean copy."""
    if not isinstance(clock, dict) or not clock:
        raise ValueError("clock must be a non-empty object")
    if _MAX_CLOCK_COMPONENTS is not None and len(clock) > _MAX_CLOCK_COMPONENTS:
        raise ValueError("clock exceeds the configured maximum component count")
    for component, tick in clock.items():
        if not isinstance(component, str) or component == "":
            raise ValueError("clock components must be non-empty strings")
        if isinstance(tick, bool) or not isinstance(tick, int) or tick < 0:
            raise ValueError("clock values must be non-negative integers")
    if replica_id not in clock:
        raise ValueError("clock must contain the replica id")
    return dict(clock)


def parse_operation_payload(raw: bytes | str | dict[str, Any], replica_id: str) -> dict[str, Any]:
    """Parse and validate an operation payload for ``replica_id``.

    Accepts a JSON document (bytes or text) or an already-decoded mapping.
    Returns a normalized operation dict. Raises ValueError when the payload
    is malformed or fails validation.
    """
    if isinstance(raw, (bytes, bytearray)):
        try:
            raw = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("body must be UTF-8 JSON") from exc
