                **EMPTY_DOCUMENT,
                "transactions": [
                    {
                        "transactionId": "tx-1",
                        "operations": [
                            {
                                "key": "k",
                                "replicaId": "r1",
                                "operationId": "o1",
                                "value": "v",
                                "clock": {"r1": 1},
                                "candidates": [],
                            }
                        ],
